mapper.select:
select

from survey_case_direction
where id = #{id,jdbcType=BIGINT}

select count(1) from ( select i.user_id from survey_investigator i left join survey_investigator_case sic on sic.survey_user_id = i.user_id and sic.delete_flag =0 left join survey_risk_case_info b on sic.survey_info_id = b.id and b.delete_flag =0 where 1 = 1 and i.delete_flag = 0
and bus_type in (${busType})
GROUP BY i.user_id ) aa;

select

from survey_case_direction
where delete_flag = 0 and survey_info_id = #{surveyInfoId,jdbcType=BIGINT} and direction_name = #{directionName,jdbcType=VARCHAR}

    and id != #{directionId,jdbcType=BIGINT}

select count(1) as directionNum,ifnull(sum(d.survey_money),0) as surveyMoney,ifnull(sum(d.entrust_money),0) as entrustMoney,ifnull(sum(d.acc_money),0) as accMoney from survey_case_direction d
left join survey_investigator_case c on d.survey_investigator_case_id = c.id
left join survey_investigator t on c.survey_user_id = t.user_id
where d.delete_flag = 0 and d.survey_info_id = #{surveyInfoId,jdbcType=BIGINT}

    and d.invalid_state = #{invalidState,jdbcType=INTEGER}


        and t.org_id = #{surveyOrgId,jdbcType=BIGINT}


     and d.survey_assorg_case_id = #{surveyAssignCaseId,jdbcType=BIGINT}

select d.survey_investigator_case_id as surveyInvestigatorCaseId,ifnull(sum(d.score),0) as score from survey_case_direction d
where DATE_FORMAT(d.create_by,'%Y%m%d') > DATE_FORMAT(#{afterTime,jdbcType=DATE},'%Y%m%d')
and d.survey_investigator_case_id != #{surveyInvestigatorCaseId,jdbcType=BIGINT}
and d.survey_info_id = #{surveyInfoId,jdbcType=BIGINT} and d.delete_flag = 0

    and d.invalid_state = #{invalidState,jdbcType=INTEGER}

group by d.survey_investigator_case_id

SELECT aa.region_name_id as regionNameId,aa.region_name as regionName,COUNT(1) AS COUNT FROM (
SELECT a.survey_info_id

    ,a.city_id AS region_name_id , a.city AS region_name


    ,MAX(a.district_id) AS region_name_id ,  IF(a.district IS NULL ,a.city,a.district)  AS region_name

FROM survey_case_direction a
LEFT JOIN survey_assign_org b  ON a.survey_assorg_case_id = b.id
LEFT JOIN survey_risk_case_info d ON a.survey_info_id = d.id
LEFT JOIN survey_consignor c ON d.entrust_org_id = c.id
WHERE a.delete_flag = 0 AND d.delete_flag=0 AND b.delete_flag=0
AND c.delete_flag=0 AND c.org_attr=2 AND c.org_state=0

    AND b.review_time IS NOT NULL AND b.review_time >= #{startTime} AND b.review_time <= #{endTime}


    AND d.entrust_report_end_date IS NOT NULL AND d.entrust_report_end_date >= #{startTime} AND d.entrust_report_end_date <= #{endTime}


    AND d.case_state=#{caseType}


    AND d.entrust_org_id in (${orgId})


    and a.province_id = #{provinceId}


    and a.city_id = #{cityId}


    GROUP BY a.survey_info_id


    GROUP BY a.id


    ,a.city_id

) aa WHERE aa.region_name IS NOT NULL GROUP BY aa.region_name_id ORDER BY COUNT DESC

SELECT aa.region_name_id as regionNameId,aa.region_name as regionName,COUNT(1) AS COUNT FROM ( SELECT a.survey_info_id
,a.province_id AS region_name_id , a.province AS region_name
,a.province_id AS region_name_id , a.province AS region_name
,a.city_id AS region_name_id , a.city AS region_name
,a.district_id AS region_name_id , a.district AS region_name
FROM survey_case_direction a LEFT JOIN survey_assign_org b ON a.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info d ON a.survey_info_id = d.id LEFT JOIN survey_consignor c ON d.entrust_org_id = c.id WHERE a.delete_flag = 0 AND d.delete_flag=0 AND b.delete_flag=0 AND c.delete_flag=0 AND c.org_attr=2 AND c.org_state=0
AND b.review_time IS NOT NULL AND b.review_time >= #{startTime} AND b.review_time <= #{endTime}
AND d.entrust_report_end_date IS NOT NULL AND d.entrust_report_end_date >= #{startTime} AND d.entrust_report_end_date <= #{endTime}
AND d.case_state=#{caseType}
AND d.entrust_org_id in (${orgId})
and a.province_id = #{provinceId}
and a.city_id = #{cityId}
and a.district_id = #{districtId}
GROUP BY a.survey_info_id
GROUP BY a.id
,a.province_id
,a.province_id
,a.city_id
,a.district_id
) aa WHERE aa.region_name IS NOT NULL GROUP BY aa.region_name_id

SELECT aa.*,MAX(aa.areaTypes) areaType FROM (
    SELECT b.survey_no AS surveyNo,a.survey_info_id AS surveyInfoId,(CASE h.parent_id WHEN 0 THEN h.id ELSE h.parent_id END) AS orgId,
    c.survey_person AS surveyPerson,e.name AS entrustOrgName,
    (CASE h.parent_id WHEN 0 THEN d.survey_org_name ELSE h.name END) AS surveyOrgName,
    (CASE a.area_type WHEN 1 THEN (CASE a.region_type WHEN 5 THEN 0 ELSE 1 END) ELSE a.area_type END) AS areaTypes,
    b.case_state AS caseState,d.create_time AS createTime,d.report_date AS reportDate,d.org_end_time AS orgEndTime,d.aging_day AS agingDay
    FROM survey_case_direction a
    LEFT JOIN survey_risk_case_info b ON a.survey_info_id = b.id
    LEFT JOIN survey_risk_case c ON b.survey_id=c.id
    LEFT JOIN survey_assign_org d ON a.survey_assorg_case_id = d.id
    LEFT JOIN survey_consignor e ON b.entrust_org_id = e.id
    LEFT JOIN survey_franchisee h ON d.survey_org_id = h.id
    WHERE  a.delete_flag=0 AND b.delete_flag=0 AND c.delete_flag=0 AND d.delete_flag=0 AND e.delete_flag=0 AND e.org_attr=2

        AND d.review_time IS NOT NULL AND d.review_time >= #{startTime} AND d.review_time <= #{endTime}


        AND b.entrust_report_end_date IS NOT NULL AND b.entrust_report_end_date >= #{startTime} AND b.entrust_report_end_date <= #{endTime}


        AND b.case_state=#{caseType}


        AND b.entrust_org_id in (${orgId})

)aa GROUP BY aa.orgId,aa.surveyInfoId HAVING areaType=#{areaType}

    limit #{pageIndex}, #{pageSize}

select count(1) from (
    SELECT aa.*,MAX(aa.areaTypes) areaType FROM (
    SELECT b.survey_no AS surveyNo,a.survey_info_id AS surveyInfoId,(CASE h.parent_id WHEN 0 THEN h.id ELSE h.parent_id END) AS orgId,
    c.survey_person AS surveyPerson,e.name AS entrustOrgName,
    (CASE h.parent_id WHEN 0 THEN d.survey_org_name ELSE h.name END) AS surveyOrgName,
    (CASE a.area_type WHEN 1 THEN (CASE a.region_type WHEN 5 THEN 0 ELSE 1 END) ELSE a.area_type END) AS areaTypes,
    b.case_state AS caseState,d.create_time AS createTime,d.report_date AS reportDate,d.org_end_time AS orgEndTime,d.aging_day AS agingDay
    FROM survey_case_direction a
    LEFT JOIN survey_risk_case_info b ON a.survey_info_id = b.id
    LEFT JOIN survey_risk_case c ON b.survey_id=c.id
    LEFT JOIN survey_assign_org d ON a.survey_assorg_case_id = d.id
    LEFT JOIN survey_consignor e ON b.entrust_org_id = e.id
    LEFT JOIN survey_franchisee h ON d.survey_org_id = h.id
    WHERE  a.delete_flag=0 AND b.delete_flag=0 AND c.delete_flag=0 AND d.delete_flag=0 AND e.delete_flag=0 AND e.org_attr=2

        AND d.review_time IS NOT NULL AND d.review_time >= #{startTime} AND d.review_time <= #{endTime}


        AND b.entrust_report_end_date IS NOT NULL AND b.entrust_report_end_date >= #{startTime} AND b.entrust_report_end_date <= #{endTime}


        AND b.case_state=#{caseType}


        AND b.entrust_org_id in (${orgId})

    )aa GROUP BY aa.orgId,aa.surveyInfoId HAVING areaType=#{areaType}
) aaa

select
        ifnull(max(a.area_type),4)
 from (
        select (case d.area_type when 1 then (case d.region_type when 5 then 0 else 1 end) else d.area_type end) as area_type  from survey_case_direction d
        where d.delete_flag = 0 and d.survey_assorg_case_id = #{surveyAssorgCaseId,jdbcType=BIGINT}
) a

select #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName,#{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, f.name as surveyOrgName, f.id as surveyOrgId, #{level} as orgLevel,(case when a.survey_org_id is null then 2 else 1 end) as orgType, IFNULL(file.num,0) as fileNum, IFNULL(haveFile.num,0) as haveFileNum, IFNULL(sound.num,0) as soundNum, IFNULL(haveSound.num,0) as haveSoundNum from survey_franchisee f left join ( select survey_org_id from survey_org_area area where state = 1 and delete_flag = 0 group by survey_org_id ) a on f.id = a.survey_org_id left join ( select COUNT(1) as num, t.surveyOrgId from ( select b.survey_org_id as surveyOrgId, d.id from survey_case_direction d LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and d.task_id in (37,35,38,50,52,49,51,39,40)
) t GROUP BY t.surveyOrgId ) file on f.id = file.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select b.survey_org_id as surveyOrgId, d.id from survey_case_direction d LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and d.task_id in (37,35,38,50,52,49,51,39,40) and d.have_file = 1
) t GROUP BY t.surveyOrgId ) haveFile on f.id = haveFile.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select b.survey_org_id as surveyOrgId, d.id from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and ti.delete_flag =0 and ti.type = 2
) t GROUP BY t.surveyOrgId ) sound on f.id = sound.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select b.survey_org_id as surveyOrgId, d.id from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and ti.delete_flag =0 and ti.type = 2 and d.have_sound = 1
) t GROUP BY t.surveyOrgId ) haveSound on f.id = haveSound.surveyOrgId
where 1=1 and f.delete_flag = 0 and f.org_state = 0
and f.bus_type in (1,3)
and f.id = #{dataRoleOrgId,jdbcType=BIGINT}
and find_in_set(f.id,#{surveyOrgIds,jdbcType=VARCHAR})

select #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName,#{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, ifnull(area.survey_area_id,area.org_id) as surveyOrgId, ifnull(area.survey_area_name,area.org_name) as surveyOrgName, #{level} as orgLevel,1 as orgType, IFNULL(file.num,0) as fileNum, IFNULL(haveFile.num,0) as haveFileNum, IFNULL(sound.num,0) as soundNum, IFNULL(haveSound.num,0) as haveSoundNum from survey_investigator area left join ( select COUNT(1) as num, t.surveyOrgId from ( select ifnull(t.survey_area_id,-1) as surveyOrgId, d.id from survey_case_direction d left join survey_investigator_case c on d.survey_investigator_case_id = c.id left join survey_investigator t on c.survey_user_id = t.user_id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and c.delete_flag = 0 and d.task_id in (37,35,38,50,52,49,51,39,40) and t.org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId ) file on ifnull(area.survey_area_id,-1) = file.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select ifnull(t.survey_area_id,t.org_id) as surveyOrgId, d.id from survey_case_direction d left join survey_investigator_case c on d.survey_investigator_case_id = c.id left join survey_investigator t on c.survey_user_id = t.user_id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and t.org_id = #{orgId,jdbcType=BIGINT} and d.task_id in (37,35,38,50,52,49,51,39,40) and d.have_file = 1
) t GROUP BY t.surveyOrgId ) haveFile on ifnull(area.survey_area_id,-1) = haveFile.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select ifnull(t.survey_area_id,t.org_id) as surveyOrgId, d.id from survey_case_direction d left join survey_investigator_case c on d.survey_investigator_case_id = c.id left join survey_investigator t on c.survey_user_id = t.user_id left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and ti.delete_flag =0 and ti.type = 2 and t.org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId ) sound on ifnull(area.survey_area_id,-1) = sound.surveyOrgId
left join ( select COUNT(1) as num, t.surveyOrgId from ( select ifnull(t.survey_area_id,t.org_id) as surveyOrgId, d.id from survey_case_direction d left join survey_investigator_case c on d.survey_investigator_case_id = c.id left join survey_investigator t on c.survey_user_id = t.user_id left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_franchisee f on f.id = b.survey_org_id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and b.delete_flag= 0 and a.delete_flag = 0 and ti.delete_flag =0 and ti.type = 2 and t.org_id = #{orgId,jdbcType=BIGINT} and d.have_sound = 1
) t GROUP BY t.surveyOrgId ) haveSound on ifnull(area.survey_area_id,-1) = haveSound.surveyOrgId where 1=1 and area.org_id = #{orgId,jdbcType=BIGINT}
and area.org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and area.survey_area_id = #{surveyAreaId,jdbcType=BIGINT}
group by area.survey_area_id

select si.real_name as surveyUserName, si.user_id as surveyUserId, si.org_id as surveyOrgId, si.org_name as surveyOrgName, #{surveyState,jdbcType=INTEGER} as surveyState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, IFNULL(file.num,0) as fileNum, IFNULL(haveFile.num,0) as haveFileNum, IFNULL(sound.num,0) as soundNum, IFNULL(haveSound.num,0) as haveSoundNum
from survey_investigator si left join ( select COUNT(1) as num, t.surveyUserId from ( select c.survey_user_id as surveyUserId from survey_case_direction d LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and d.task_id in (37,35,38,50,52,49,51,39,40)
) t GROUP BY t.surveyUserId ) file on si.user_id = file.surveyUserId
left join ( select COUNT(1) as num, t.surveyUserId from ( select c.survey_user_id as surveyUserId from survey_case_direction d LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and d.task_id in (37,35,38,50,52,49,51,39,40) and d.have_file = 1
) t GROUP BY t.surveyUserId ) haveFile on si.user_id = haveFile.surveyUserId
left join ( select COUNT(1) as num, t.surveyUserId from ( select c.survey_user_id as surveyUserId from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and ti.delete_flag =0 and ti.type = 2
) t GROUP BY t.surveyUserId ) sound on si.user_id = sound.surveyUserId
left join ( select COUNT(1) as num, t.surveyUserId from ( select c.survey_user_id as surveyUserId from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and ti.delete_flag =0 and ti.type = 2 and d.have_sound = 1
) t GROUP BY t.surveyUserId ) haveSound on si.user_id = haveSound.surveyUserId
left join bus_user_role bur on bur.user_id = si.user_id where bur.role_id = 50
and find_in_set(si.user_id,#{surveyInvestigators,jdbcType=VARCHAR})
and si.org_id = #{orgId,jdbcType=BIGINT}

select investigator.surveyUserId, investigator.surveyOrgId, investigator.surveyUserName, #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, #{surveyState,jdbcType=INTEGER} as surveyState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, IFNULL(file.num,0) as fileNum , IFNULL(haveFile.num,0) as haveFileNum, IFNULL(sound.num,0) as soundNum, IFNULL(haveSound.num,0) as haveSoundNum from ( select t.surveyUserId,t.surveyOrgId,t.surveyUserName from ( select c.survey_user_id as surveyUserId, c.survey_user_name as surveyUserName,si.org_id as surveyOrgId from survey_case_direction d LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0
and si.survey_area_id = #{orgId,jdbcType=BIGINT}
and b.survey_org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and b.survey_org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null
and b.survey_org_id = #{orgId,jdbcType=BIGINT}
and d.task_id in (37,35,38,50,52,49,51,39,40)
) t GROUP BY t.surveyOrgId,t.surveyUserId )investigator LEFT JOIN ( select COUNT(1) as num, t.surveyUserId,t.surveyOrgId from ( select c.survey_user_id as surveyUserId, si.org_id as surveyOrgId from survey_case_direction d LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and d.task_id in (37,35,38,50,52,49,51,39,40)
and si.survey_area_id = #{orgId,jdbcType=BIGINT}
and b.survey_org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and b.survey_org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null
and b.survey_org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId,t.surveyUserId ) file on investigator.surveyUserId = file.surveyUserId LEFT JOIN ( select COUNT(1) as num, t.surveyUserId,t.surveyOrgId from ( select c.survey_user_id as surveyUserId, si.org_id as surveyOrgId from survey_case_direction d LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and d.task_id in (37,35,38,50,52,49,51,39,40) and d.have_file =1
and si.survey_area_id = #{orgId,jdbcType=BIGINT}
and b.survey_org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and b.survey_org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null
and b.survey_org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId,t.surveyUserId ) haveFile on investigator.surveyUserId = haveFile.surveyUserId LEFT JOIN ( select COUNT(1) as num, t.surveyUserId,t.surveyOrgId from ( select c.survey_user_id as surveyUserId, si.org_id as surveyOrgId from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and ti.delete_flag =0 and ti.type = 2
and si.survey_area_id = #{orgId,jdbcType=BIGINT}
and b.survey_org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and b.survey_org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null
and b.survey_org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId,t.surveyUserId ) sound on investigator.surveyUserId = sound.surveyUserId LEFT JOIN ( select COUNT(1) as num, t.surveyUserId,t.surveyOrgId from ( select c.survey_user_id as surveyUserId, si.org_id as surveyOrgId from survey_case_direction d left join survey_task_info ti on d.task_id = ti.id LEFT JOIN survey_investigator_case c on d.survey_investigator_case_id = c.id LEFT JOIN survey_assign_org b on d.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = d.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id where d.delete_flag = 0 and c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 and ti.delete_flag =0 and ti.type = 2 and d.have_sound = 1
and si.survey_area_id = #{orgId,jdbcType=BIGINT}
and b.survey_org_id = #{dataRoleOrgId,jdbcType=BIGINT}
and b.survey_org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null
and b.survey_org_id = #{orgId,jdbcType=BIGINT}
) t GROUP BY t.surveyOrgId,t.surveyUserId ) haveSound on investigator.surveyUserId = haveSound.surveyUserId

select d.* from survey_case_direction d left join survey_assign_org o on d.survey_assorg_case_id = o.id and o.delete_flag = 0 left join survey_franchisee f on o.survey_org_id = f.id left join survey_channel_cost_new c on d.id = c.survey_direction_id and c.delete_flag = 0 where 1 = 1 and d.delete_flag = 0 and c.id is null
and d.survey_info_id = #{surveyInfoId,jdbcType=BIGINT}
and (f.id = #{orgId,jdbcType=BIGINT} or f.parent_id = #{orgId,jdbcType=BIGINT})
